const MODAL_FOCUS={ps3DetailModal:'[data-ps3-close="ps3DetailModal"]',ps3CreateModal:'#ps3CreateName',ps3WorkstreamModal:'#ps3WsTitle',ps3MilestoneModal:'#ps3MilestoneTitle'};
function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.add('hidden'),2400)}
async function googleCalendarCall(action,{method='GET',body=null,params=null}={}){if(!(await rt.session.ensure()))throw new Error('로그인이 필요합니다.');const u=new URL(rt.config.url+'/functions/v1/google-calendar');if(action)u.searchParams.set('action',action);if(params)Object.entries(params).forEach(([k,v])=>u.searchParams.set(k,String(v)));const d=await api(u.toString(),{method,body});if(d?.error)throw new Error(d.error||'Google Calendar 요청 실패');return d}
async function googleCalendarStatus({fresh=false}={}){const cached=window.__KPTU_GOOGLE_STATE__;if(!fresh&&cached&&typeof cached.connected==='boolean'&&Array.isArray(cached.calendars)){googleCalendarState=cached;return cached}try{googleCalendarState=await googleCalendarCall('status');window.__KPTU_GOOGLE_STATE__={...(window.__KPTU_GOOGLE_STATE__||{}),...(googleCalendarState||{})};return googleCalendarState}catch(e){googleCalendarState={connected:false,calendars:[],error:e?.message||String(e)};return googleCalendarState}}
const writableGoogleCalendars=s=>(s?.calendars||[]).filter(x=>['owner','writer'].includes(x.accessRole||''));
function googleStateMessage(s){if(!s?.connected)return s?.error||'Google Calendar 연결이 필요합니다. 일정 탭에서 Google Calendar를 연결한 뒤 다시 시도해 주세요.';if(s?.warning)return s.warning;return'쓰기 가능한 Google 세부캘린더가 없습니다.'}
async function prepareMilestoneGoogle(editing=false){const sel=$('#ps3MilestoneGoogle'),hint=$('#ps3MilestoneGoogleHint');if(!sel)return false;sel.disabled=true;sel.innerHTML='';const linked=!!(editingMilestone?.google_event_id&&editingMilestone?.google_calendar_id);if(editing&&!linked){sel.innerHTML='<option value="">기존 Web2 일정 · Google 연결 없음</option>';if(hint)hint.textContent='기존 일정은 자동으로 Google Calendar에 만들지 않습니다.';return true}if(hint)hint.textContent='Google Calendar 연결 상태를 확인하는 중…';const s=await googleCalendarStatus({fresh:true});if(editing&&linked){const id=editingMilestone.google_calendar_id,cal=(s?.calendars||[]).find(x=>x.id===id);sel.innerHTML=`<option value="${esc(id)}">${esc(cal?.summary||id)} (현재 연결)</option>`;sel.value=id;if(!s?.connected){if(hint)hint.textContent=googleStateMessage(s);return false}if(s?.warning){if(hint)hint.textContent=s.warning;return false}if(!cal||!['owner','writer'].includes(cal.accessRole||'')){if(hint)hint.textContent='현재 연결된 Google 캘린더를 수정할 권한이 없습니다.';return false}if(hint)hint.textContent='현재 연결된 Google 일정을 함께 수정합니다.';return true}sel.innerHTML='<option value="">Google 세부캘린더 선택</option>';if(!s?.connected){if(hint)hint.textContent=googleStateMessage(s);return false}const rows=writableGoogleCalendars(s);if(!rows.length){if(hint)hint.textContent=googleStateMessage(s);return false}sel.insertAdjacentHTML('beforeend',rows.map(x=>`<option value="${esc(x.id)}">${esc(x.summary||x.id)}${x.primary?' (기본)':''}</option>`).join(''));const selected=new Set(s.selected||[]),preferred=rows.find(x=>selected.has(x.id)||(x.primary&&selected.has('primary')))||rows.find(x=>x.primary)||rows[0];if(preferred)sel.value=preferred.id;sel.disabled=false;if(hint)hint.textContent='새 프로젝트 일정은 선택한 Google 세부캘린더에 반드시 생성됩니다.';return true}
async function ensureWritableGoogleCalendar(calendarId){const s=await googleCalendarStatus({fresh:true});if(!s?.connected)throw new Error(googleStateMessage(s));const cal=writableGoogleCalendars(s).find(x=>x.id===calendarId);if(!cal)throw new Error(s?.warning||'선택한 Google 캘린더에 쓰기 권한이 없습니다. 다시 연결하거나 다른 캘린더를 선택해 주세요.');return cal}
function milestoneEventPayload(body,projectId=current?.id){return{workspace_id:wid,project_id:projectId,workstream_id:body.workstream_id||null,title:body.title,description:body.notes||null,event_type:MILESTONE_EVENT_TYPE[body.milestone_type]||'other',start_at:body.start_at,end_at:body.end_at||null,location:null,created_by:user.id,body:body.notes||'',calendar_scope:'personal'}}
async function createLinkedMilestoneEvent(body,projectId=current?.id){if(!body.start_at)return null;const rows=await api('/rest/v1/app_events',{method:'POST',body:milestoneEventPayload(body,projectId),prefer:'return=representation'});return rows?.[0]||null}
async function syncLinkedMilestoneEvent(eventId,body,projectId=current?.id){if(!eventId||!body.start_at)return;const payload=milestoneEventPayload(body,projectId);delete payload.workspace_id;delete payload.created_by;await api(`/rest/v1/app_events?id=eq.${encodeURIComponent(eventId)}`,{method:'PATCH',body:{...payload,updated_at:new Date().toISOString()}})}
function googleMilestonePayload(action,calendarId,body,eventId=null){if(!calendarId)throw new Error('Google 세부캘린더를 선택해 주세요.');if(!body.start_at)throw new Error('일시를 입력해 주세요.');const start=new Date(body.start_at),end=new Date(start.getTime()+60*60*1000);return{action,calendar_id:calendarId,...(eventId?{event_id:eventId}:{}),title:body.title,memo:body.notes||'',location:'',all_day:false,start_iso:start.toISOString(),end_iso:end.toISOString()}}
async function createGoogleMilestone(calendarId,body){const d=await googleCalendarCall('',{method:'POST',body:googleMilestonePayload('create-event',calendarId,body)});if(!d?.event?.id)throw new Error('Google Calendar 생성 응답에 일정 ID가 없습니다.');return d.event}
async function updateGoogleMilestone(calendarId,eventId,body){if(!eventId)throw new Error('연결된 Google 일정 ID가 없습니다.');const d=await googleCalendarCall('',{method:'POST',body:googleMilestonePayload('update-event',calendarId,body,eventId)});if(!d?.event?.id)throw new Error('Google Calendar 수정 응답에 일정 ID가 없습니다.');return d.event}
async function deleteGoogleMilestone(calendarId,eventId){if(!calendarId||!eventId)throw new Error('연결된 Google 일정 식별자가 없습니다.');return googleCalendarCall('',{method:'POST',body:{action:'delete-event',calendar_id:calendarId,event_id:eventId}})}
async function deleteLinkedMilestoneEvent(eventId){if(eventId)await api(`/rest/v1/app_events?id=eq.${encodeURIComponent(eventId)}`,{method:'DELETE'})}
async function refreshGoogleMilestones(){try{if(typeof window.__KPTU_RELOAD_GOOGLE_EVENTS__==='function')await window.__KPTU_RELOAD_GOOGLE_EVENTS__();else if(typeof window.KPTUCalendarPersistence?.refresh==='function')await window.KPTUCalendarPersistence.refresh()}catch(e){console.warn('project milestone google refresh failed',e)}}
function milestoneBodyFromRecord(m){return{workstream_id:m?.workstream_id||null,title:m?.title||'',milestone_type:m?.milestone_type||'action',status:m?.status||'planned',start_at:m?.start_at||null,end_at:m?.end_at||null,notes:m?.notes||null}}
function openModal(id,{trigger=document.activeElement,initialFocus=null}={}){const m=$('#'+id);if(!m)return;const wasHidden=m.classList.contains('hidden');m.classList.remove('hidden');m.setAttribute('aria-hidden','false');if(wasHidden)window.KPTUA11y?.dialog.activate(m,{trigger,initialFocus:initialFocus||MODAL_FOCUS[id]||null,onRequestClose:()=>m.querySelector(`[data-ps3-close="${id}"]`)?.click()})}
