function openMilestone(id=''){editingMilestone=id?detail.milestones.find(x=>x.id===id):null;$('#ps3MilestoneHeading').textContent=editingMilestone?'주요 일정 수정':'주요 일정 추가';$('#ps3MilestoneTitle').value=editingMilestone?.title||'';$('#ps3MilestoneAt').value=localInput(editingMilestone?.start_at);$('#ps3MilestoneNotes').value=editingMilestone?.notes||'';$('#ps3MilestoneDelete').classList.toggle('hidden',!editingMilestone);$('#ps3MilestoneState').textContent='';openModal('ps3MilestoneModal');prepareMilestoneGoogle(!!editingMilestone).catch(e=>{$('#ps3MilestoneGoogleHint').textContent=e?.message||String(e)})}
async function saveLegacyMilestone(body){const old=milestoneBodyFromRecord(editingMilestone);let createdEvent=null;try{await api(`/rest/v1/app_project_milestones?id=eq.${editingMilestone.id}`,{method:'PATCH',body});if(editingMilestone.event_id)await syncLinkedMilestoneEvent(editingMilestone.event_id,body,editingMilestone.project_id);else if(body.start_at){createdEvent=await createLinkedMilestoneEvent(body,editingMilestone.project_id);if(createdEvent?.id)await api(`/rest/v1/app_project_milestones?id=eq.${editingMilestone.id}`,{method:'PATCH',body:{event_id:createdEvent.id}})}}catch(e){const rollback=[];if(createdEvent?.id)try{await deleteLinkedMilestoneEvent(createdEvent.id)}catch(x){rollback.push(x)}try{await api(`/rest/v1/app_project_milestones?id=eq.${editingMilestone.id}`,{method:'PATCH',body:{...old,event_id:editingMilestone.event_id||null}})}catch(x){rollback.push(x)}if(editingMilestone.event_id&&old.start_at)try{await syncLinkedMilestoneEvent(editingMilestone.event_id,old,editingMilestone.project_id)}catch(x){rollback.push(x)}if(rollback.length){console.error('legacy milestone rollback failed',{error:e,rollback});throw new Error(`Web2 일정 수정 실패 후 복구에도 실패했습니다: ${rollback.map(x=>x?.message||String(x)).join(' / ')}`)}throw e}}
async function saveGoogleLinkedMilestone(body){const old=milestoneBodyFromRecord(editingMilestone),calendarId=editingMilestone.google_calendar_id,eventId=editingMilestone.google_event_id;await ensureWritableGoogleCalendar(calendarId);await updateGoogleMilestone(calendarId,eventId,body);let createdEvent=null;try{await api(`/rest/v1/app_project_milestones?id=eq.${editingMilestone.id}`,{method:'PATCH',body});if(editingMilestone.event_id)await syncLinkedMilestoneEvent(editingMilestone.event_id,body,editingMilestone.project_id);else{createdEvent=await createLinkedMilestoneEvent(body,editingMilestone.project_id);if(!createdEvent?.id)throw new Error('Web2 연결 일정 생성 결과를 확인할 수 없습니다.');await api(`/rest/v1/app_project_milestones?id=eq.${editingMilestone.id}`,{method:'PATCH',body:{event_id:createdEvent.id}})}}catch(e){const rollback=[];if(createdEvent?.id)try{await deleteLinkedMilestoneEvent(createdEvent.id)}catch(x){rollback.push(x)}try{await api(`/rest/v1/app_project_milestones?id=eq.${editingMilestone.id}`,{method:'PATCH',body:{...old,event_id:editingMilestone.event_id||null}})}catch(x){rollback.push(x)}if(editingMilestone.event_id&&old.start_at)try{await syncLinkedMilestoneEvent(editingMilestone.event_id,old,editingMilestone.project_id)}catch(x){rollback.push(x)}try{await updateGoogleMilestone(calendarId,eventId,old)}catch(x){rollback.push(x)}if(rollback.length){console.error('google-linked milestone rollback failed',{error:e,rollback});throw new Error(`Web2 project record 생성 실패 후 rollback 실패: ${rollback.map(x=>x?.message||String(x)).join(' / ')}`)}throw new Error(`Web2 project record 생성 실패: ${e?.message||e}. Google 변경은 되돌렸습니다.`)}}
async function saveMilestone(){const title=$('#ps3MilestoneTitle').value.trim(),st=$('#ps3MilestoneState'),at=$('#ps3MilestoneAt').value;if(!title){st.textContent='제목을 입력해 주세요.';return}const body={workstream_id:editingMilestone?.workstream_id||null,title,milestone_type:editingMilestone?.milestone_type||'action',status:editingMilestone?.status||'planned',start_at:at?new Date(at).toISOString():null,end_at:editingMilestone?.end_at||null,notes:$('#ps3MilestoneNotes').value.trim()||null};if(editingMilestone?.event_id&&!body.start_at){st.textContent='연결된 일정은 일시를 비울 수 없습니다.';return}if(!editingMilestone&&!body.start_at){st.textContent='일시를 입력해 주세요.';return}try{if(editingMilestone){if(editingMilestone.google_event_id&&editingMilestone.google_calendar_id)await saveGoogleLinkedMilestone(body);else await saveLegacyMilestone(body);closeModal('ps3MilestoneModal');await refreshDetail();await refreshGoogleMilestones();toast('주요 일정을 수정했습니다.');return}const calendarId=$('#ps3MilestoneGoogle').value;if(!calendarId){st.textContent='Google 세부캘린더를 선택해 주세요.';return}await ensureWritableGoogleCalendar(calendarId);let googleEvent=null,event=null,milestone=null,stage='Google event 생성';try{googleEvent=await createGoogleMilestone(calendarId,body);stage='Web2 연결 일정 생성';event=await createLinkedMilestoneEvent(body,current.id);if(!event?.id)throw new Error('Web2 연결 일정 생성 결과를 확인할 수 없습니다.');stage='Web2 project record 생성';const rows=await api('/rest/v1/app_project_milestones',{method:'POST',body:{project_id:current.id,...body,event_id:event.id,child_project_id:null,google_calendar_id:googleEvent.calendarId||calendarId,google_event_id:googleEvent.id,sort_order:(detail.milestones.length+1)*10,created_by:user.id},prefer:'return=representation'});milestone=rows?.[0]||null;if(!milestone?.id)throw new Error('프로젝트 일정 생성 결과를 확인할 수 없습니다.')}catch(e){const rollback=[];if(milestone?.id)try{await api(`/rest/v1/app_project_milestones?id=eq.${milestone.id}`,{method:'DELETE'})}catch(x){rollback.push(x)}if(event?.id)try{await deleteLinkedMilestoneEvent(event.id)}catch(x){rollback.push(x)}if(googleEvent?.id)try{await deleteGoogleMilestone(googleEvent.calendarId||calendarId,googleEvent.id)}catch(x){rollback.push(x)}if(rollback.length){console.error('new milestone rollback failed',{stage,error:e,rollback});throw new Error(`${stage} 실패 후 rollback 실패: ${rollback.map(x=>x?.message||String(x)).join(' / ')}`)}throw new Error(`${stage} 실패: ${e?.message||e}. 생성된 기록은 남기지 않았습니다.`)}closeModal('ps3MilestoneModal');await refreshDetail();await refreshGoogleMilestones();toast('주요 일정을 추가했습니다.')}catch(e){st.textContent=e?.message||String(e)}}
async function restoreDeletedMilestone(snapshot,body,{restoreLocal,restoreGoogle}){const rollback=[],patch={};if(restoreLocal)try{const event=await createLinkedMilestoneEvent(body,snapshot.project_id);if(!event?.id)throw new Error('Web2 연결 일정 복구 결과가 없습니다.');patch.event_id=event.id}catch(e){rollback.push(e)}if(restoreGoogle)try{const event=await createGoogleMilestone(snapshot.google_calendar_id,body);patch.google_calendar_id=event.calendarId||snapshot.google_calendar_id;patch.google_event_id=event.id}catch(e){rollback.push(e)}if(!rollback.length&&Object.keys(patch).length)try{await api(`/rest/v1/app_project_milestones?id=eq.${snapshot.id}`,{method:'PATCH',body:patch})}catch(e){rollback.push(e)}return rollback}
async function delMilestone(){if(!editingMilestone||!confirm(`“${editingMilestone.title}” 주요 일정을 삭제할까요?`))return;const snapshot={...editingMilestone},body=milestoneBodyFromRecord(snapshot),linked=!!(snapshot.google_event_id&&snapshot.google_calendar_id),st=$('#ps3MilestoneState');let localDeleted=false,googleDeleted=false;try{if(linked){await ensureWritableGoogleCalendar(snapshot.google_calendar_id);await deleteGoogleMilestone(snapshot.google_calendar_id,snapshot.google_event_id);googleDeleted=true}if(snapshot.event_id){await deleteLinkedMilestoneEvent(snapshot.event_id);localDeleted=true}await api(`/rest/v1/app_project_milestones?id=eq.${snapshot.id}`,{method:'DELETE'});closeModal('ps3MilestoneModal');await refreshDetail();await refreshGoogleMilestones();toast('주요 일정을 삭제했습니다.')}catch(e){const rollback=await restoreDeletedMilestone(snapshot,body,{restoreLocal:localDeleted,restoreGoogle:googleDeleted});if(rollback.length){console.error('milestone delete rollback failed',{error:e,rollback});st.textContent=`프로젝트 일정 삭제 실패 후 rollback 실패: ${rollback.map(x=>x?.message||String(x)).join(' / ')}`;return}st.textContent=(localDeleted||googleDeleted)?`프로젝트 일정 삭제에 실패해 삭제한 연결 일정을 복구했습니다: ${e?.message||e}`:(e?.message||String(e))}}
async function ensureFeature(view){const loader=window.KPTUViewLoader;if(loader?.isLoaded?.(view))return true;if(loader?.load){try{await loader.load(view);return true}catch(e){console.error('project feature load failed',view,e);return false}}return false}
